					content: [
						{
							type: "text",
							text: "No SWITCHBOARD_DIAGRAM_URL is set, so there is no screen to draw on. Describe the structure in words instead.",
						},
					],
					details: {},
					isError: true,
				};
			}
			try {
				const resp = await fetch(DIAGRAM_URL, {
