async fn deliver_page_reply_if_current(
    state: &AppState,
    reply: &crate::pbx::Reply,
    status: Value,
    generation: u64,
) -> bool {
    let _transition = state.0.operation_transition.lock().await;
    if generation != state.0.turn_generation.load(Ordering::Acquire) {
        return false;
    }
    if !reply.text.is_empty() {
