                    // state. History/status/diagram are authoritative; activity
                    // and already-missed audio are intentionally ephemeral.
                    events = state.0.events.subscribe();
                    if send_snapshot(&mut socket, &state).await.is_err() {
                        return;
                    }
                }
                Err(_) => return,
            },
        }
    }
}

